<template>
  <!-- Sequential Execution Banner with New Button -->
  <div class="container banner-row-container">
    <div class="row items-center justify-between">
      <q-banner v-if="isMultipleExportEnabledForAnyDocType" class="docbits-info-banner col" dense inline-actions>
        <template v-slot:avatar>
          <q-icon name="info" color="primary" size="sm" />
        </template>
        <span class="text-weight-bold">{{ $t('sequential_execution') }}:</span>
        {{ $t('sequential_execution_description') }}
      </q-banner>
      <q-space v-else />
      <f-btn
        class="q-ml-md"
        icon="add"
        data-cy="add-integration-button"
        @click="addNewConfig()"
        :label="$t('new')"
      />
    </div>
  </div>

  <!-- export button -->
  <div class="container" v-if="!configurations">
    <div style="text-align: center; line-height: 35px; letter-spacing: 2px">
      <q-btn
        style="margin-bottom: 20px; pointer-events: none"
        size="25px"
        round
        class="integration-icon"
        icon="upload"
      />
      <br />
      <b>{{ $t('heading') }}</b> <br />
      {{ $t('subheading') }} <br />
      <q-btn
        style="margin-top: 20px; letter-spacing: 2px"
        color="primary"
        :label="$t('addintegration')"
        @click="addNewConfig()"
      />
    </div>
  </div>

  <!-- export grid -->
  <div class="container">
    <div class="full-width">
      <DocBitsTable
        :rows="configurations || []"
        :columns="columns"
        :loading="processing"
        row-key="id"
        table-id="export_table"
        :features="{
          sorting: true,
          clientSideSort: true,
          filtering: false,
          selection: true,
          bulkActions: true,
          rowActions: true,
          resizable: false,
          pagination: false,
          columnReorder: true,
          columnSettings: false,
          stickyFirstColumn: false,
          stickyLastColumn: true,
        }"
        :row-actions="rowActions"
        :column-order="columnOrder"
        :selected-rows="selectedIds"
        @selection-change="onSelectionChange"
        no-data-label="no_configurations"
        table-class="export-table-height"
        flat-style
        @row-action="handleRowAction"
        @row-click="handleRowClick"
        @column-reorder="handleColumnReorder"
      >
        <!-- Status column with badge -->
        <template #body-cell-status="{ row }">
          <q-badge
            rounded
            :color="row.is_active ? 'green' : 'red-14'"
          />
        </template>

        <!-- Title column -->
        <template #body-cell-title="{ row }">
          {{ row.title }}
        </template>

        <!-- Doc type column with label lookup -->
        <template #body-cell-doc_type="{ row }">
          {{ getDocTypeLabel(row) }}
        </template>

        <!-- Sub organizations column with name lookup -->
        <template #body-cell-sub_organizations="{ row }">
          {{ getSubOrgName(row) }}
        </template>

        <!-- Export method column -->
        <template #body-cell-export_method="{ row }">
          {{ row.export_method }}
        </template>
      </DocBitsTable>
    </div>
  </div>

  <!-- Bulk Action Bar -->
  <q-slide-transition>
    <div v-show="selectedIds.length > 0" class="bulk-action-bar">
      <div class="bulk-action-bar__content">
        <div class="bulk-action-bar__info">
          <q-icon name="check_circle" color="primary" size="sm" />
          <span class="text-weight-medium">
            {{ selectedIds.length }} {{ $t('selected') }}
          </span>
        </div>
        <div class="bulk-action-bar__actions">
          <q-btn outline dense icon="check_circle" :label="$t('activate')" color="positive" :disable="bulkProcessing" @click="bulkActivate" />
          <q-btn outline dense icon="cancel" :label="$t('deactivate')" color="warning" :disable="bulkProcessing" @click="bulkDeactivate" />
          <q-separator vertical inset class="q-mx-sm" />
          <q-btn outline dense icon="delete" :label="$t('delete')" color="negative" :disable="bulkProcessing" @click="bulkDeleteConfirmation = true" />
        </div>
        <q-btn flat dense icon="close" :label="$t('cancel')" color="grey-7" :disable="bulkProcessing" @click="clearSelection" />
      </div>
      <q-inner-loading :showing="bulkProcessing">
        <q-spinner-dots size="50px" color="primary" />
      </q-inner-loading>
    </div>
  </q-slide-transition>

  <!-- Bulk Delete Confirmation Dialog -->
  <q-dialog v-model="bulkDeleteConfirmation" persistent>
    <q-card style="min-width: 400px;">
      <q-card-section class="bg-negative text-white q-pa-md">
        <div class="row items-center">
          <q-icon name="warning" size="sm" color="white" class="q-mr-sm" />
          <div class="text-h6">{{ $t('warning_document_will_be_deleted') }}</div>
        </div>
      </q-card-section>
      <q-card-section class="q-pt-md">
        <p>{{ $t('confirm_bulk_delete_message', { count: selectedIds.length }) }}</p>
      </q-card-section>
      <q-card-actions align="right" class="q-pa-md">
        <f-btn appearance="cancel" :label="$t('cancel')" v-close-popup />
        <f-btn :label="$t('delete')" v-close-popup @click="bulkDelete" />
      </q-card-actions>
    </q-card>
  </q-dialog>

  <Loader />

  <q-dialog v-model="deleteConfirmation" persistent>
    <q-card style="min-width: 400px;">
      <q-card-section class="bg-primary text-white q-pa-md">
        <div class="row items-center">
          <q-icon name="warning" size="sm" color="white" class="q-mr-sm" />
          <div class="text-h6">{{ $t('warning_document_will_be_deleted') }}</div>
        </div>
      </q-card-section>

      <q-card-section class="q-pt-md">
        <p>{{ $t('export_sure') }}</p>
      </q-card-section>

      <q-card-actions align="right" class="q-pa-md">
        <f-btn appearance="cancel" :label="$t('cancel')" data-cy="cancel-card" v-close-popup />
        <f-btn
          :label="$t('delete')"
          data-cy="done-card"
          v-close-popup
          @click="deleteConfiguration()"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref, Ref, computed } from 'vue';
import Loader from 'src/components/Loader.vue';
import helperMixin from 'src/mixins/helperMixin.js';
import { useDocExportStore, useDropdownStore, useDocAttributesStore } from 'src/store/main';
import { storeToRefs } from 'pinia';
import { exportApiService } from 'src/services';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions/index';
import cache from 'src/utils/cache';
import { CONSTANTS } from 'src/constants';
import { DocBitsTable } from 'src/components/Table';
import type {
  UnifiedTableColumn,
  RowActionItem,
  RowActionPayload,
} from 'src/components/Table';
import { useTranslate } from '@tolgee/vue';

export default defineComponent({
  mixins: [helperMixin, cache],
  components: {
    Loader,
    DocBitsTable,
  },
  watch: {
    processing: {
      handler: function (newVal, oldVal) {
        if (newVal === false) {
          this.hideLoading();
        } else {
          this.showLoading();
        }
      },
    },
  },
  async mounted() {
    this.processing = true;
    this.loadColumnOrder();
    await this.getSubOrgsList();
    this.fillDocTypeAndSubTypesListIfEmpty();
    await this.getExportConfigurations();
    this.getDocTypeAllSettings();
    this.processing = false;
  },
  methods: {
    editConfiguration(configuration: any) {
      const export_type = configuration.export_method;
      if (!export_type) {
        notify.error(
          this.$t('ERROR_EXPORT_METHOD_NOT_FOUND'),
        );
        return;
      }

      // Navigate to edit URL
      var obj_snapshot = JSON.parse(JSON.stringify(configuration));
      this.setSelectedExportForEdit(obj_snapshot);
      this.$router.push(`/settings/export/${configuration.id}`);
    },

    addNewConfig() {
      this.configId = 0;
      this.clearOnlySelectionConfigState();
      // Navigate to new URL
      this.$router.push('/settings/export/new');
    },

    loadColumnOrder() {
      const savedOrder = this.getDataByKey(CONSTANTS.export_columns_order) as string;
      if (savedOrder) {
        this.columnOrder = JSON.parse(savedOrder);
      }
    },

    handleColumnReorder(newOrder: string[]) {
      this.columnOrder = newOrder;
      this.setDataToLocalStorage(CONSTANTS.export_columns_order, JSON.stringify(newOrder));
    },

    onSelectionChange(payload: { selectedIds: string[]; selectedRows: any[]; totalSelected: number; totalAvailable: number }) {
      this.selectedIds = payload.selectedIds;
    },

    clearSelection() {
      this.selectedIds = [];
    },

    async bulkActivate() {
      await this.bulkToggleActive(true);
    },

    async bulkDeactivate() {
      await this.bulkToggleActive(false);
    },

    async bulkToggleActive(activate: boolean) {
      this.bulkProcessing = true;
      try {
        for (const id of this.selectedIds) {
          const config = this.configurations?.find((c: any) => String(c.id) === String(id));
          if (!config) continue;
          if (config.is_active === activate) continue;
          await this.handleDisability(config, config.is_active);
        }
        this.clearSelection();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.bulkProcessing = false;
      }
    },

    async bulkDelete() {
      this.bulkProcessing = true;
      try {
        for (const id of this.selectedIds) {
          const config = this.configurations?.find((c: any) => String(c.id) === String(id));
          if (!config) continue;
          if (config.is_watchdog) {
            await exportApiService.deleteWatchdogConfiguration(String(id));
          } else {
            await exportApiService.delete(String(id));
          }
        }
        this.clearSelection();
        this.clearStateForExportDialog();
        this.getExportConfigurations();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.bulkProcessing = false;
      }
    },

    handleRowAction(payload: RowActionPayload) {
      const row = payload.row;
      if (payload.action === 'activate' || payload.action === 'deactivate') {
        this.handleDisability(row, row.is_active);
      } else if (payload.action === 'edit') {
        this.editConfiguration(row);
      } else if (payload.action === 'test_connection') {
        this.testConnection(row);
      } else if (payload.action === 'delete') {
        this.deleteConfirmation = true;
        this.configId = row.id;
      }
    },

    handleRowClick(payload: { row: any }) {
      this.editConfiguration(payload.row);
    },

    async deleteConfiguration() {
      try {
        this.processing = true;
        if (this.isWatchdogConfig) {
          await exportApiService.deleteWatchdogConfiguration(
            this.configId.toString(),
          );
        } else {
          await exportApiService.delete(this.configId.toString());
        }
        this.clearStateForExportDialog();
        this.getExportConfigurations();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },

    async handleDisability(configuration: any, is_active: boolean) {
      try {
        is_active = !is_active;
        this.processing = true;

        if (configuration.is_watchdog) {
          // For Watchdog configs, update via Watchdog API
          const response = await exportApiService.updateWatchdogConfiguration(
            configuration.id.toString(),
            { enabled: is_active },
          );
          if (response && response.success === false) {
            throw { message: response.message };
          }
        } else {
          // For regular configs, use standard API
          const response = await exportApiService.updateActive(
            configuration.id.toString(),
            is_active,
          );
          if (!response.success || response.success !== true) {
            throw { message: response.message };
          }
        }

        configuration.is_active = is_active;
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
      }
    },

    getDocTypeLabel(configuration: any) {
      const doc_type = this.doc_type_list.find(
        (item: any) => item.value === configuration.doc_type,
      ) as dynamicObj;
      return doc_type ? String(doc_type.label) : String(configuration.doc_type);
    },

    getSubOrgName(configuration: any) {
      if (!configuration.sub_org_id) {
        return '';
      }

      const sub_org = this.subOrgList.find(
        (item: any) => item.value === configuration.sub_org_id,
      ) as dynamicObj;
      if (!sub_org) {
        return '';
      }
      return String(sub_org.label) || '';
    },

    async testConnection(configuration: any) {
      try {
        this.showLoading();

        const data = {
          config_id: configuration.id,
        };
        let response;

        if (configuration.export_method === this.export_types.SFTP) {
          response = await exportApiService.testSFTP(data);
        }

        if (configuration.export_method === this.export_types.SMB_WITH_JPL) {
          response = await exportApiService.testSMB(data);
        }

        if (response.success === false) {
          throw { message: response.message };
        }

        notify.success(this.$t('test_connection_success'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
  },
  setup() {
    const { t } = useTranslate();
    const doc_export_store = useDocExportStore();
    const {
      getExportConfigurations,
      setSelectedExportForEdit,
      clearStateForExportDialog,
      clearOnlySelectionConfigState,
    } = doc_export_store;
    const {
      configurations,
      processing,
      export_types,
    } = storeToRefs(doc_export_store) as {
      configurations: Ref<
        Array<{
          id: number | string;
          title: string;
          doc_type: string;
          sub_org_id: string;
          export_method: string;
          is_active: boolean;
          is_watchdog?: boolean;
        }>
      >;
      processing: Ref<boolean>;
      export_types: Ref<any>;
    };

    const dropdown_store = useDropdownStore();
    const { fillDocTypeAndSubTypesListIfEmpty, getSubOrgsList } =
      dropdown_store;
    const { doc_type_list, subOrgList } = storeToRefs(dropdown_store);

    const doc_attribute_store = useDocAttributesStore();
    const { getDocTypeAllSettings, getSettingsByDocTypeAndSettingKey } = doc_attribute_store;

    const isMultipleExportEnabledForAnyDocType = computed(() => {
      const settings = doc_attribute_store.allDocTypesSettings;
      if (!settings || Object.keys(settings).length === 0) return false;
      return Object.keys(settings).some((docType) =>
        getSettingsByDocTypeAndSettingKey(docType, CONSTANTS.ALLOW_MULTIPLE_EXPORT_CONFIGURATIONS) === true,
      );
    });

    const test_connection_types = [
      doc_export_store.export_types.SFTP,
      doc_export_store.export_types.SMB_WITH_JPL,
    ];

    // Column definitions for DocBitsTable
    // Order: Status, Document Type, Sub-Org, Title, Execution Order (conditional), Export Method
    const columns = computed<UnifiedTableColumn[]>(() => {
      const cols: UnifiedTableColumn[] = [
        {
          name: 'status',
          label: '',
          field: 'is_active',
          sortable: false,
          align: 'center',
        },
        {
          name: 'doc_type',
          label: t.value('doc_type'),
          field: 'doc_type',
          sortable: true,
          align: 'left',
        },
        {
          name: 'sub_organizations',
          label: t.value('sub_organizations'),
          field: 'sub_org_id',
          sortable: true,
          align: 'left',
        },
        {
          name: 'title',
          label: t.value('title'),
          field: 'title',
          sortable: true,
          align: 'left',
        },
      ];

      if (isMultipleExportEnabledForAnyDocType.value) {
        cols.push({
          name: 'execution_order',
          label: t.value('execution_order'),
          field: 'execution_order',
          sortable: true,
          align: 'left',
        });
      }

      cols.push({
        name: 'export_method',
        label: t.value('export_method'),
        field: 'export_method',
        sortable: true,
        align: 'left',
      });

      return cols;
    });

    // Row actions with conditional visibility
    const rowActions: RowActionItem[] = [
      {
        key: 'activate',
        label: 'activate',
        icon: 'check_circle',
        color: 'positive',
        show: (row: any) => !row.is_active,
      },
      {
        key: 'deactivate',
        label: 'deactivate',
        icon: 'cancel',
        color: 'grey-7',
        show: (row: any) => row.is_active,
      },
      {
        key: 'edit',
        label: 'edit',
        icon: 'edit',
        color: 'primary',
      },
      {
        key: 'test_connection',
        label: 'test_connection',
        icon: 'wifi_tethering',
        color: 'grey-7',
        separator: true,
        show: (row: any) => test_connection_types.includes(row.export_method),
      },
      {
        key: 'delete',
        label: 'delete',
        icon: 'delete',
        color: 'negative',
        separator: true,
      },
    ];

    return {
      export_types,
      subOrgList,
      getSubOrgsList,
      doc_type_list,
      fillDocTypeAndSubTypesListIfEmpty,
      setSelectedExportForEdit,
      deleteConfirmation: ref(false),
      bulkDeleteConfirmation: ref(false),
      configId: 0 as number | string,
      isWatchdogConfig: ref(false),
      selectedIds: ref<string[]>([]),
      bulkProcessing: ref(false),
      getExportConfigurations,
      configurations,
      processing,
      clearStateForExportDialog,
      clearOnlySelectionConfigState,
      columns,
      rowActions,
      columnOrder: ref<string[]>([]),
      t,
      getDocTypeAllSettings,
      isMultipleExportEnabledForAnyDocType,
    };
  },
});
</script>

